// wfSlackbotGlyph is Slack's slackbot-color (the Slackbot steps' icon in
// 8uOE): four colours on a white tile, drawn by wfDrawSlackbot.
const wfSlackbotGlyph = "slackbot-color"

// wfHasGlyph reports whether wfDrawGlyph can draw name.
func wfHasGlyph(name string) bool {
	if name == wfSlackbotGlyph {
		return true
	}
	if _, ok := wfGlyphs[name]; ok {
		return true
	}
	return icons.Has(name)
}

// wfDrawGlyph draws name at size dp in col: one of Slack's glyphs above,
// the Slackbot logo, or a registered icon.
func wfDrawGlyph(gtx layout.Context, name string, size unit.Dp, col color.NRGBA) layout.Dimensions {
	px := gtx.Dp(size)
	if name == wfSlackbotGlyph {
		wfDrawSlackbot(gtx, px)
		return layout.Dimensions{Size: image.Pt(px, px)}
	}
	d, ok := wfGlyphs[name]
	if !ok {
		return icons.Get(name)(gtx, size, col)
	}
	sc := float32(px) / 20
	paint.FillShape(gtx.Ops, col, clip.Outline{Path: icons.ClipPath(gtx, d, sc)}.Op())
	return layout.Dimensions{Size: image.Pt(px, px)}
}

// wfDrawSlackbot is Slack's slackbot-color: the white rounded tile, its
// four coloured corners, the eyes and the smile.
func wfDrawSlackbot(gtx layout.Context, px int) {
	sc := float32(px) / 20
	rgb := func(v uint32) color.NRGBA {
		return color.NRGBA{R: uint8(v >> 16), G: uint8(v >> 8), B: uint8(v), A: 0xff}
	}
	fill := func(c uint32, d string) {
		paint.FillShape(gtx.Ops, rgb(c), clip.Outline{Path: icons.ClipPath(gtx, d, sc)}.Op())
	}
	stroke := func(c uint32, w float32, d string) {
		paint.FillShape(gtx.Ops, rgb(c), clip.Stroke{Path: icons.ClipPath(gtx, d, sc), Width: w * sc}.Op())
	}
	disc := func(c uint32, cx, cy, rx, ry float32) {
		r := image.Rect(int((cx-rx)*sc+.5), int((cy-ry)*sc+.5), int((cx+rx)*sc+.5), int((cy+ry)*sc+.5))
		paint.FillShape(gtx.Ops, rgb(c), clip.Ellipse(r).Op(gtx.Ops))
	}
	tile := image.Rect(int(2*sc+.5), int(2*sc+.5), int(18*sc+.5), int(18*sc+.5))
	paint.FillShape(gtx.Ops, rgb(0xffffff), clip.UniformRRect(tile, int(4*sc+.5)).Op(gtx.Ops))
	fill(0xedb22e, "M18 13.999a4 4 0 0 1-4 4h-3.562A7.61 7.61 0 0 1 18 10.438z")
	fill(0x2eb57d, "M14 2a4 4 0 0 1 4 4v3.56A7.607 7.607 0 0 1 10.438 2z")
	fill(0xe01e59, "M2 10.438a7.61 7.61 0 0 1 7.562 7.561H6a4 4 0 0 1-4-4z")
	fill(0x36c4f0, "M9.562 2A7.607 7.607 0 0 1 2 9.56V6a4 4 0 0 1 4-4z")
	stroke(0x3d0f3d, 1.781, "M3.094 7.376c.375-.375 1.125-.688 2.094-.688m11.718.504c-.375-.375-.968-.656-2.093-.656")
	for _, x := range [][2]float32{{15.281, 15.769}, {4.719, 5.206}} {
		disc(0xffffff, x[0], 10.031, 1.516+.266, 1.516+.266) // the eye's .531 white outline
		disc(0x3d0f3d, x[0], 10.031, 1.516-.266, 1.516-.266)
		disc(0xffffff, x[1], 9.55, .454, .449)
	}
	stroke(0x3d0f3d, .938, "M7.781 10.563c1.172.859 2.953 1.015 4.438 0")
	stroke(0xe8e8e8, .938, "M9.094 12.734c.39.125 1.203.22 1.781 0")
}
